def count_partitions(n: int, k: int, x: int) -> int:
    # Initialize a 2D array to store the results
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Initialize the first row with 1
    for i in range(k + 1):
        dp[0][i] = 1

    # Fill in the table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i < x or j == 0:
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i - x][j - 1] + dp[i][j - 1]

    # Return the result
    return dp[n][k]

