def max_herb_value(T, M, herbs):
    # Initialize the dp table with 0s
    dp = [0] * (T + 1)

    # Loop through each herb
    for herb in herbs:
        # Get the time and value of the herb
        time, value = herb

        # Loop through each time step
        for t in range(T, time - 1, -1):
            # Check if the current time step is valid
            if t >= time:
                # Update the dp table with the maximum of the current value and the previous value
                dp[t] = max(dp[t], dp[t - time] + value)

    # Return the maximum value in the dp table
    return max(dp)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n+1) for _ in range(V+1)]

    # Fill in the table
    for i in range(1, V+1):
        for j in range(1, n+1):
            # If the current volume is greater than the available space, we can't fit anything
            if i < volumes[j-1]:
                dp[i][j] = dp[i][j-1]
            # Otherwise, we can fit the current volume, so we try to fit the remaining items in the box
            else:
                dp[i][j] = max(dp[i-volumes[j-1]][j-1], dp[i][j-1])

    # The minimum remaining space is the difference between the total capacity and the maximum occupied volume
    return V - dp[V][n]

